import React, { useState } from 'react';
import './navFilters.css';
import { useDispatch, useSelector } from 'react-redux';

import {
  Filter_Tipo_Caballero,
  Filter_Tipo_Dama,
  Filter_Quitar,
  Filter_Tipo_Mixto
} from '../../Redux/Actions/Usuario/Action-user';

const NavFilter = () => {
  const dispatch = useDispatch();
  const cards = useSelector((state) => state.CARDS);
  const [selectedType, setSelectedType] = useState('');
  const [filters, setFilters] = useState({
    zapatilla: false,
    botas: false,
    sandalia: false,
    formales: false
  });

  const handleTypeChange = (type) => {
    setSelectedType(type);

    switch (type) {
      case 'caballero':
        dispatch(Filter_Tipo_Caballero(cards));
        break;
      case 'dama':
        dispatch(Filter_Tipo_Dama(cards));
        break;
      case 'mixto':
        dispatch(Filter_Tipo_Mixto(cards));
        break;
      default:
        break;
    }
  };

  const handleQuitarFilter = () => {
    setSelectedType('');
    setFilters({
      zapatilla: false,
      botas: false,
      sandalia: false,
      formales: false
    });
    dispatch(Filter_Quitar(cards));
  };

  const handleSelect = (filter) => {
    setFilters((prevFilters) => ({
      ...prevFilters,
      [filter]: !prevFilters[filter]
    }));

    if(filter){
      alert(filter)
      //dispatch(Filter_Zandalias(filter))
    }
    // Aquí puedes despachar una acción para filtrar las tarjetas según el filtro seleccionado
    // dispatch(Filter_XYZ(cards));
  };

  return (
    <div className="navfilter-container">
      <div className="navfilter-section">
        <h2 className="navfilter-subtitle-titulo">Filtros</h2>
        <div onClick={handleQuitarFilter} className="filter-null">Quitar Filtros</div>
        <h4 className="navfilter-subtitle">Tipo</h4>
        <div className="navfilter-option">
          <input
            type="radio"
            id="caballero"
            name="type"
            value="caballero"
            checked={selectedType === 'caballero'}
            onChange={() => handleTypeChange('caballero')}
          />
          <label htmlFor="caballero">Caballero</label>
        </div>
        <div className="navfilter-option">
          <input
            type="radio"
            id="dama"
            name="type"
            value="dama"
            checked={selectedType === 'dama'}
            onChange={() => handleTypeChange('dama')}
          />
          <label htmlFor="dama">Dama</label>
        </div>
        <div className="navfilter-option">
          <input
            type="radio"
            id="mixto"
            name="type"
            value="mixto"
            checked={selectedType === 'mixto'}
            onChange={() => handleTypeChange('mixto')}
          />
          <label htmlFor="mixto">Mixto</label>
        </div>

<hr/>


        <h4 className="navfilter-subtitle">Categoría</h4>
        <div className="navfilter-option">
          <input
            type="checkbox"
            id="zapatillas"
            name="zapatillas"
            checked={filters.zapatilla}
            onChange={() => handleSelect('zapatilla')}
          />
          <label htmlFor="zapatillas">Zapatillas</label>
        </div>
        <div className="navfilter-option">
          <input
            type="checkbox"
            id="botas"
            name="botas"
            checked={filters.botas}
            onChange={() => handleSelect('botas')}
          />
          <label htmlFor="botas">Botas</label>
        </div>
        <div className="navfilter-option">
          <input
            type="checkbox"
            id="sandalias"
            name="sandalias"
            checked={filters.sandalia}
            onChange={() => handleSelect('sandalias')}
          />
          <label htmlFor="sandalias">Sandalias</label>
        </div>
        <div className="navfilter-option">
          <input
            type="checkbox"
            id="formales"
            name="formales"
            checked={filters.formales}
            onChange={() => handleSelect('formales')}
          />
          <label htmlFor="formales">Formales</label>
        </div>
      </div>

      {/* Otros filtros aquí */}
    </div>
  );
};

export default NavFilter;
